#!/bin/bash
# generated by usub 0.1.0 (backend=local)

cd /work
usub_logdir=/work/logs
usub_run="job.$(date +%Y%m%d-%H%M%S).$$"
mkdir -p "$usub_logdir"
usub_tasks=
usub_task() {
  export USUB_INDEX="$1"
  ( python sim.py --seed ${USUB_INDEX}
  ) >"$usub_logdir/$usub_run.$1.out" 2>"$usub_logdir/$usub_run.$1.err"
  usub_rc=$?
  if [ "$usub_rc" -ne 0 ]; then echo "usub: task $1 failed (exit $usub_rc)" >&2; return 1; fi
}
export -f usub_task
export usub_logdir usub_run usub_tasks
seq 1 2 100 | xargs -P 10 -I{} bash -c 'usub_task "$1"' _ {}
usub_rc=$?
echo "usub: logs in $usub_logdir/$usub_run.*" >&2
exit $usub_rc
